#!/usr/bin/env python3
# Generated by Claude Fable 5 (Anthropic)
"""Existing overhead summaries → standalone English LaTeX tables (task 1).
Writes paper/tables/{isaac_overhead,autoware_overhead,trace_health}.tex.
Sources: overhead_isaac/summary.csv + the Autoware analyzer (live) + known
trace-health numbers (notes/overhead_isaac_campaign.txt)."""
import csv
import os
import subprocess
import sys

ROOT = os.path.expanduser('~/fish_traces/overhead_isaac')
OUT = 'paper/tables'
os.makedirs(OUT, exist_ok=True)
E = lambda s: s.replace('_', r'\_')


def isaac():
    rows = {}
    with open(f'{ROOT}/summary.csv') as f:
        for r in csv.DictReader(f):
            if r['mode'] in ('base', 'lttng', 'nsys') and r.get('fps_mean'):
                rows.setdefault(r['bench'], {})[r['mode']] = r
    L = ['% Generated by Claude Fable 5 (Anthropic)',
         r'\begin{table*}[t]\centering\small',
         r'\caption{Isaac ROS tracing overhead: throughput (fps, mean$\pm$std over'
         r' 3 runs, measured by \texttt{ros2\_benchmark} itself) per mode.'
         r' $\Delta$ vs.\ the untraced baseline.}\label{tab:isaac-overhead}',
         r'\begin{tabular}{lrrrrrr}', r'\toprule',
         r'benchmark & baseline & LTTng-only & $\Delta$ & LTTng+nsys & $\Delta$ &'
         r' jitter$_{base}$ [ms] \\', r'\midrule']
    for b in sorted(rows):
        d = rows[b]
        if 'base' not in d:
            continue
        fb = float(d['base']['fps_mean']); sb = float(d['base']['fps_std'] or 0)
        def cell(m):
            if m not in d:
                return '--', '--'
            fm = float(d[m]['fps_mean']); sm = float(d[m]['fps_std'] or 0)
            return (f'{fm:.1f}$\\pm${sm:.1f}',
                    f'{(fm-fb)/fb*100:+.1f}\\%')
        cl, dl = cell('lttng'); cn, dn = cell('nsys')
        jit = d['base'].get('jit_mean_mean') or ''
        try:
            jit = f"{float(d['base']['jit_mean_mean']):.1f}"
        except (ValueError, KeyError, TypeError):
            jit = '--'
        L.append(f"{E(b)} & {fb:.1f}$\\pm${sb:.1f} & {cl} & {dl} & {cn} & {dn} & {jit} \\\\")
    L += [r'\bottomrule', r'\end{tabular}', r'\end{table*}']
    open(f'{OUT}/isaac_overhead.tex', 'w').write('\n'.join(L) + '\n')
    print(f'→ {OUT}/isaac_overhead.tex')


def autoware():
    # live: analyzer markdown → tex
    out = subprocess.run(
        [sys.executable, 'scripts/autoware_runs/analyze_overhead_modes.py',
         os.path.expanduser('~/fish_traces/overhead_aw_20260831_133353')],
        capture_output=True, text=True, timeout=600)
    lines = [l for l in out.stdout.splitlines() if l.startswith('|') and '---' not in l]
    L = ['% Generated by Claude Fable 5 (Anthropic)',
         r'\begin{table*}[t]\centering\small',
         r"\caption{Autoware \texttt{logging\_simulator} overhead: Autoware's own"
         r' internal measurements (\texttt{/diagnostics}), mean$\pm$std over 3 runs'
         r' per mode; $\Delta$ vs.\ baseline. Zero topic-state-monitor violations'
         r' in every mode.}\label{tab:aw-overhead}',
         r'\begin{tabular}{lrrr}', r'\toprule']
    import re as _re
    tsm = startup = None
    for i, ln in enumerate(lines):
        cells = [c.strip() for c in ln.strip('|').split('|')]
        cells = [E(c).replace('±', r'$\pm$').replace('Δ', r'$\Delta$')
                 .replace('%', r'\%').replace('—', '--') for c in cells]
        if 'tsm violations' in cells[0]:
            # integers, bold, last row
            cells = [_re.sub(r'(\d+)\.\d+', r'\1', c) for c in cells]
            tsm = ' & '.join(rf'\textbf{{{c}}}' for c in cells) + r' \\'
            continue
        if 'tsm NotReceived' in cells[0]:
            startup = ' & '.join(cells) + r' \\'
            continue
        L.append(' & '.join(cells) + r' \\')
        if i == 0:
            L.append(r'\midrule')
    if startup:
        L += [r'\midrule', startup]
    if tsm:
        L += [r'\midrule', tsm]
    L += [r'\bottomrule', r'\end{tabular}', r'\end{table*}']
    open(f'{OUT}/autoware_overhead.tex', 'w').write('\n'.join(L) + '\n')
    print(f'→ {OUT}/autoware_overhead.tex')


def health():
    L = ['% Generated by Claude Fable 5 (Anthropic)',
         r'\begin{table}[t]\centering\small',
         r'\caption{Trace health across the overhead campaigns.}'
         r'\label{tab:trace-health}',
         r'\begin{tabular}{lrrr}', r'\toprule',
         r'campaign & traced runs & events & discarded \\', r'\midrule',
         r'Isaac ROS (13 benchmarks) & 90 & 60.1\,M & 3\,178 (0.005\,\%) \\',
         r'Autoware logging\_simulator & 6 & 30.5\,M & 0 \\',
         r'\bottomrule', r'\end{tabular}', r'\end{table}']
    open(f'{OUT}/trace_health.tex', 'w').write('\n'.join(L) + '\n')
    print(f'→ {OUT}/trace_health.tex')


if __name__ == '__main__':
    isaac()
    autoware()
    health()
